<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIntegration} from '../../stores/integration'
import {useDetection} from '../../composables/useDetection'
import {allPages,ApiError,errorText,localApi} from '../../services/local/api'
import {submissionDone,submissionKey} from '../../services/local/submission'
import {exportLocalReport,localReportText} from '../../services/local/report'
import {eventIdsFromQuery,taskLabel} from '../../services/local/fields'
import type {Diagnosis,Report,ReportSummary} from '../../services/local/types'
import Panel from '../../components/Panel.vue'
import ServiceState from '../../components/local/ServiceState.vue'
import LocalChart from '../../components/local/LocalChart.vue'
import {time} from '../../utils'
import {useDesktopDirty} from '../../composables/useDesktopDirty'
const route=useRoute(),router=useRouter(),service=useIntegration(),diagnosis=ref<Diagnosis>(),report=ref<Report>(),selected=ref<string[]>([]),note=ref(''),error=ref(''),busy=ref(false),exporting=ref(false),diagnosisHistory=ref<Diagnosis[]>([]),reports=ref<ReportSummary[]>([]),historyError=ref(''),reportPage=ref(1),archiveFilter=ref('all'),chart=ref<InstanceType<typeof LocalChart>>(),draftDate=ref(new Date().toISOString())
const conflict=ref(false),serverNote=ref<string>(),feedback=ref('')
const sourceId=computed(()=>report.value?.detectionId??String(route.query.detectionId??diagnosis.value?.detectionId??'')),resource=useDetection(sourceId)
const task=computed(()=>report.value?.snapshot.task??resource.task.value),result=computed(()=>report.value?.snapshot.result??resource.result.value),events=computed(()=>report.value?.snapshot.events??resource.events.value),points=computed(()=>report.value?.snapshot.points??resource.points.value)
const canDiagnose=computed(()=>false),canStore=computed(()=>!!service.runtime?.capabilities.reportPersistence),eventSet=computed(()=>events.value.filter(e=>selected.value.includes(e.id)))
const matchingDiagnosis=computed(()=>diagnosis.value?.status==='success'&&diagnosis.value.detectionId===task.value?.id&&JSON.stringify([...diagnosis.value.eventIds].sort())===JSON.stringify([...selected.value].sort())?diagnosis.value:null)
const current=computed<Report|undefined>(()=>{if(report.value)return {...report.value,note:note.value};if(!task.value||!result.value)return undefined;return {id:`LOCAL-${task.value.id}`,title:'换热站运行状态异常检测报告',detectionId:task.value.id,diagnosisId:matchingDiagnosis.value?.id??null,eventIds:[...selected.value],version:0,revision:0,createdAt:draftDate.value,archivedAt:null,note:note.value,snapshot:{task:task.value,result:result.value,events:eventSet.value,points:points.value,diagnosis:matchingDiagnosis.value}}})
const sections=computed(()=>current.value?localReportText(current.value):[]),filteredReports=computed(()=>reports.value.filter(r=>archiveFilter.value==='all'||(archiveFilter.value==='archived'?!!r.archivedAt:!r.archivedAt))),series=computed(()=>[{name:'异常分数',unit:'分数',color:'#2563eb',data:points.value.map(p=>[p.timestamp,p.score] as [string,number])},{name:'阈值',unit:'分数',color:'#c2410c',data:points.value.map(p=>[p.timestamp,p.threshold] as [string,number])}])
useDesktopDirty(()=>!!current.value&&note.value!==(report.value?.note??''))
let controller:AbortController|undefined,historyController:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,generation=0,loadedRoute=''
watch(archiveFilter,()=>reportPage.value=1)
watch([()=>route.query.reportId,()=>route.query.diagnosisId,()=>route.params.id,()=>route.query.detectionId,()=>route.query.eventIds,()=>service.ready],async()=>{
 const run=++generation;controller?.abort();clearTimeout(timer);controller=new AbortController();const c=controller
 if(!service.ready)return
 const routeKey=JSON.stringify([route.query.reportId,route.query.diagnosisId,route.params.id,route.query.detectionId,route.query.eventIds]),preserve=loadedRoute===routeKey;loadedRoute=routeKey
 if(!preserve){diagnosis.value=undefined;report.value=undefined;note.value='';selected.value=eventIdsFromQuery(route.query.eventIds);draftDate.value=new Date().toISOString();conflict.value=false;serverNote.value=undefined}else if(report.value&&note.value!==report.value.note)return
 error.value=''
 try{if(route.query.reportId){if(!canStore.value)throw new Error('本机后端尚未启用报告存档。');const r=await localApi.report(String(route.query.reportId));if(run!==generation)return;report.value=r;note.value=r.note;selected.value=[...r.eventIds];diagnosis.value=r.snapshot.diagnosis??undefined}
 else {const id=String(route.query.diagnosisId??route.params.id??'');if(id){if(!canDiagnose.value)throw new Error('本机后端尚未启用原因诊断。');throw new Error('原因分析功能已取消，请从数据监测打开检测报告。')}}}catch(e){if(!c.signal.aborted)error.value=errorText(e)}
},{immediate:true})
watch(events,rows=>{if(!rows.length)return;selected.value=selected.value.filter(id=>rows.some(e=>e.id===id))})
async function loadHistory(){historyController?.abort();historyController=new AbortController();const c=historyController;historyError.value='';if(!service.ready)return
 try{const [d,r]=await Promise.all([canDiagnose.value?allPages(p=>localApi.diagnoses(p,c.signal)):Promise.resolve([]),canStore.value?allPages(p=>localApi.reports(p,c.signal)):Promise.resolve([])]);if(!c.signal.aborted){diagnosisHistory.value=d;reports.value=r}}catch(e){if(!c.signal.aborted)historyError.value=errorText(e)}}
watch([()=>service.ready,()=>service.revision],loadHistory,{immediate:true})
async function save(){if(!current.value||!canStore.value)throw new Error('报告存档能力未启用。');if(report.value){const saved=await localApi.note(report.value.id,note.value,report.value.revision);report.value=saved;return saved}
 const body={detectionId:current.value.detectionId,eventIds:[...selected.value],diagnosisId:matchingDiagnosis.value?.id??null};let saved=await localApi.createReport(body.detectionId,body.eventIds,body.diagnosisId,submissionKey('report',body));submissionDone('report');report.value=saved
 if(note.value!==saved.note){saved=await localApi.note(saved.id,note.value,saved.revision);report.value=saved}await loadHistory();return saved
}
function reportError(e:unknown){error.value=errorText(e);conflict.value=e instanceof ApiError&&e.code==='REVISION_CONFLICT'}
async function latest(){if(!report.value||busy.value||exporting.value)return;busy.value=true;error.value='';try{const r=await localApi.report(report.value.id);if(r.archivedAt&&note.value!==r.note){serverNote.value=r.note;error.value='最新版本已归档。当前输入保留在下方，请复制备注并创建新版本后编辑。'}else serverNote.value=r.note;report.value=r;conflict.value=false;feedback.value='已读取最新版本，请核对已保存备注与当前输入后再保存。'}catch(e){reportError(e)}finally{busy.value=false}}
async function remember(){if(report.value)await router.replace({path:'/diagnosis',query:{reportId:report.value.id}})}
async function mutate(action:'save'|'archive'|'version'){if(busy.value||exporting.value)return;busy.value=true;error.value='';feedback.value='';try{
 if(action==='version'&&report.value){if(!report.value.archivedAt&&note.value!==report.value.note)await save();const body={id:report.value.id,expectedRevision:report.value.revision},scope='report-version-'+body.id;const r=await localApi.version(body.id,body.expectedRevision,submissionKey(scope,body));submissionDone(scope);await router.push({path:'/diagnosis',query:{reportId:r.id}});feedback.value='新版本已创建，旧版本保持不变。'}
 else{const r=await save();if(action==='archive')report.value=await localApi.archive(r.id,r.revision);note.value=report.value!.note;await remember();feedback.value=action==='archive'?'报告已归档，旧版本已锁定。':'报告与备注已保存。'}
 conflict.value=false;serverNote.value=undefined;await loadHistory()
 }catch(e){reportError(e)}finally{busy.value=false}}
async function exportFile(format:'docx'|'pdf'){if(!current.value||exporting.value||busy.value)return;exporting.value=true;error.value='';feedback.value='';try{
 if(report.value?.archivedAt&&note.value!==report.value.note)throw new Error('归档备注与当前输入不同，请创建新版本并保存后导出。')
 const image=chart.value?.image()??'';let snapshot=current.value;if(canStore.value&&(!report.value||(!report.value.archivedAt&&note.value!==report.value.note))){snapshot=await save();await remember()}
 await exportLocalReport(snapshot,format,image);feedback.value=`${format==='docx'?'Word':'PDF'} 已生成，内容来自${snapshot.version?'已保存的 V'+snapshot.version:'当前临时报告'}。`
 }catch(e){reportError(e)}finally{exporting.value=false}}
function chooseAll(event:globalThis.Event){selected.value=(event.target as HTMLInputElement).checked?events.value.map(e=>e.id):[]}
onBeforeUnmount(()=>{generation++;controller?.abort();historyController?.abort();clearTimeout(timer)})
</script>
<template><div class="page-stack local-page"><div class="page-actions"><div><h2>检测报告</h2><p class="muted">查看异常事件和检测证据，保存备注、归档并导出报告。</p></div><RouterLink :to="sourceId?'/detections/'+encodeURIComponent(sourceId):'/detections'">返回数据监测</RouterLink></div><ServiceState><p v-if="error||resource.error.value" class="error" role="alert">{{error||resource.error.value}}</p><p v-if="feedback" role="status">{{feedback}}</p><button v-if="conflict" :disabled="busy||exporting" @click="latest">读取最新版本，保留当前备注</button><p v-if="serverNote!==undefined" class="local-notice">最新已保存备注：{{serverNote||'无'}}。请核对下方当前输入后再保存。</p><p v-if="resource.loading.value" role="status">正在读取来源任务…</p><template v-if="task&&result"><Panel title="来源与异常事件选择"><p class="local-source">{{task.contextSnapshot.enterprise.name}} / {{task.contextSnapshot.network.name}} / {{task.contextSnapshot.segment.name}} / {{task.contextSnapshot.station.name}}</p><p>来源检测 {{task.id}} · {{taskLabel[task.status]}} · {{task.modelSnapshot.isDemo?'示例模型':'本站登记模型'}} {{task.modelSnapshot.version}}</p><div class="local-actions"><label><input type="checkbox" :checked="!!events.length&&selected.length===events.length" :disabled="!!report||busy" @change="chooseAll"/>全选 {{events.length}} 项</label></div><label v-for="e in events" :key="e.id" class="local-event-choice"><input v-model="selected" type="checkbox" :value="e.id" :aria-label="'诊断选择 '+e.id" :disabled="!!report||busy"/><span><strong>{{e.title}}</strong><small>{{e.id}} · {{time(e.start)}} — {{time(e.end)}}</small><small>峰值分数 {{e.peak_score}}</small></span></label><p v-if="!events.length" class="empty">本次检测没有确认告警。</p><LocalChart ref="chart" :series="series" :events="eventSet"/></Panel><Panel title="报告预览与导出"><template #tools><span class="badge orange">{{report?'V'+report.version+' · '+(report.archivedAt?'已归档':'已保存'):'临时报告 · 未存档'}}</span></template><p v-if="!canStore" class="muted">后端尚未启用报告持久化。备注仅保留在当前页面，可随 Word/PDF 导出；不会提示已归档。</p><p v-else-if="!report" class="muted">保存或导出后，报告证据与所选事件将固定；归档后备注锁定，可创建新版本继续编辑。</p><div v-for="section in sections" :key="section.heading" class="local-report-section"><h3>{{section.heading}}</h3><p v-for="(line,i) in section.lines" :key="i">{{line}}</p></div><label>报告备注<textarea v-model="note" rows="4" maxlength="2000" aria-label="本机报告备注" :disabled="!!report?.archivedAt||busy||exporting"/></label><div class="local-actions mt"><button :disabled="!canStore||busy||exporting||!!report?.archivedAt||!selected.length" @click="mutate('save')">保存报告与备注</button><button :disabled="!canStore||busy||exporting||!!report?.archivedAt||!selected.length" @click="mutate('archive')">保存并归档</button><button v-if="report" :disabled="!canStore||busy||exporting" @click="mutate('version')">创建新版本</button><button class="primary" :disabled="exporting||busy||!selected.length" @click="exportFile('docx')">{{exporting?'导出中…':'导出 Word'}}</button><button class="primary" :disabled="exporting||busy||!selected.length" @click="exportFile('pdf')">导出 PDF</button></div></Panel></template><p v-else-if="!sourceId" class="empty">请从数据监测单选或多选确认告警事件，或打开下面的历史记录。</p><Panel title="报告历史与归档"><template #tools><button @click="loadHistory">刷新历史</button></template><p v-if="historyError" class="error" role="alert">{{historyError}}</p><label>归档状态<select v-model="archiveFilter" aria-label="本机报告归档状态"><option value="all">全部报告</option><option value="archived">已归档</option><option value="draft">未归档</option></select></label><div class="table-wrap"><table><thead><tr><th>报告</th><th>版本</th><th>存档状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in filteredReports.slice((reportPage-1)*20,reportPage*20)" :key="r.id"><td>{{r.title}}</td><td>{{r.version}}</td><td>{{r.archivedAt?'已归档':'未归档'}}</td><td><RouterLink :to="{path:'/diagnosis',query:{reportId:r.id}}">查看报告</RouterLink></td></tr><tr v-if="!filteredReports.length"><td colspan="4" class="empty">{{canStore?'暂无已保存报告':'后端尚未启用本机报告存档'}}</td></tr></tbody></table></div><div class="pagination"><span>{{filteredReports.length}} 条 · 第 {{reportPage}} 页</span><button :disabled="reportPage===1" @click="reportPage--">上一页</button><button :disabled="reportPage*20>=filteredReports.length" @click="reportPage++">下一页</button></div></Panel></ServiceState></div></template>
